// Generate the two brand artefacts the product needs from the design registry.
//
//   mockups/assets/brands.json   the reviewed registry, generated by the mockup
//                                build from the Simple Icons and SVG Logos sets
//
// Produces:
//   src/core/brands.js           names and hostnames, for import detection
//   src/web/brands/*.svg         the marks, so the product does not reach into
//                                the design folder at runtime
//
// Run with: npm run brands

import { readFileSync, writeFileSync, mkdirSync, copyFileSync, readdirSync, rmSync } from "node:fs";

const ROOT = new URL("../", import.meta.url);
const registry = JSON.parse(readFileSync(new URL("mockups/assets/brands.json", ROOT), "utf8"));

// Brands whose domain is not the product host we want to match on.
const HOST_OVERRIDES = {
  groq: "console.groq.com",
  stripe: "dashboard.stripe.com",
  neon: "console.neon.tech",
  cloudflare: "dash.cloudflare.com",
  aws: "aws.amazon.com",
  google: "myaccount.google.com",
  github: "github.com",
  openai: "platform.openai.com",
  anthropic: "console.anthropic.com",
  vercel: "vercel.com",
  supabase: "supabase.com",
  linear: "linear.app",
  resend: "resend.com",
  netlify: "app.netlify.com",
  cloudinary: "console.cloudinary.com",
  digitalocean: "cloud.digitalocean.com",
  twilio: "console.twilio.com",
  sendgrid: "app.sendgrid.com",
  mongodb: "cloud.mongodb.com",
  planetscale: "app.planetscale.com",
  turso: "turso.tech",
  upstash: "console.upstash.com",
  railway: "railway.app",
  flydotio: "fly.io",
  render: "dashboard.render.com",
};

// Words that are too generic to match on their own during import detection.
const SKIP_NAME_MATCH = new Set(["app", "api", "cloud", "one", "box", "home", "meta", "square", "check", "scale", "note", "todo", "hue", "twitch"]);

const names = {};
const hosts = [];
for (const b of registry.brands) {
  names[b.slug] = b.name;
  const host = HOST_OVERRIDES[b.slug] || b.domain;
  if (host && host.includes(".")) hosts.push([host, b.slug]);
}
// Longest host first so "console.groq.com" wins over a bare "groq.com".
hosts.sort((a, b) => b[0].length - a[0].length);

const lines = [
  "// Generated by tools/brands.mjs from mockups/assets/brands.json.",
  "// Do not edit by hand. Rebuild with: npm run brands",
  "",
  "/** slug -> display name */",
  "export const BRAND_NAMES = {",
  ...Object.entries(names).map(([slug, name]) => `  ${JSON.stringify(slug)}: ${JSON.stringify(name)},`),
  "};",
  "",
  "/** [hostname, slug], longest hostname first */",
  "export const BRAND_BY_HOST = [",
  ...hosts.map(([host, slug]) => `  [${JSON.stringify(host)}, ${JSON.stringify(slug)}],`),
  "];",
  "",
  "/** Slugs that hold a mark, in src/web/brands */",
  "export const BRAND_SLUGS = new Set(Object.keys(BRAND_NAMES));",
  "",
  "/** Names too generic to match alone during import detection. */",
  `export const GENERIC_NAMES = new Set(${JSON.stringify([...SKIP_NAME_MATCH])});`,
  "",
];
writeFileSync(new URL("src/core/brands.js", ROOT), lines.join("\n"));

const src = new URL("mockups/assets/brands/", ROOT);
const dest = new URL("src/web/brands/", ROOT);
rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });
let copied = 0;
for (const file of readdirSync(src)) {
  if (!file.endsWith(".svg")) continue;
  copyFileSync(new URL(file, src), new URL(file, dest));
  copied += 1;
}

console.log(`brands.js: ${Object.keys(names).length} names, ${hosts.length} hosts`);
console.log(`src/web/brands: ${copied} svg files`);
